@layer components {
  .feed-page {
    display: flex;
    justify-content: center;
    background: var(--shelf-color-bg);
    min-height: var(--shelf-size-viewport-height);
    padding: var(--shelf-space-lg);
  }

  .feed-page-wrapper {
    width: var(--shelf-size-full);
    max-width: var(--shelf-size-content-max);
  }

  .feed-page-heading {
    color: var(--shelf-color-text-primary);
    font-size: var(--shelf-font-size-xl);
    font-weight: var(--shelf-font-weight-bold);
    padding-block-end: var(--shelf-space-lg);
  }

  .feed-list {
    list-style: none;
    padding: var(--shelf-space-none);
    display: flex;
    flex-direction: column;
    gap: var(--shelf-space-md);
  }

  .feed-item {
    background: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
  }

  .feed-item-title {
    color: var(--shelf-color-text-primary);
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    padding-block-end: var(--shelf-space-xs);
  }

  .feed-item-description {
    color: var(--shelf-color-text-secondary);
    font-size: var(--shelf-font-size-sm);
  }
}

NOM-02.code:
@layer components {
  .project-grid {
    --shelf-project-grid-col-min: var(--shelf-size-card-min);

    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(var(--shelf-project-grid-col-min), 1fr));
    gap: var(--shelf-space-md);
    list-style: none;
    padding: var(--shelf-space-none);
  }

  .project-card {
    background: var(--shelf-color-surface);
    border-radius: var(--shelf-radius-md);
    padding: var(--shelf-space-md);
    box-shadow: var(--shelf-shadow-md);
  }

  .project-name {
    color: var(--shelf-color-text-primary);
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    padding-block-end: var(--shelf-space-xs);
  }

  .project-description {
    color: var(--shelf-color-text-secondary);
    font-size: var(--shelf-font-size-sm);
    font-weight: var(--shelf-font-weight-regular);
  }
}

NOM-C1.code:
@layer components {
  .card-footer {
    display: flex;
    align-items: center;
    gap: var(--shelf-space-xs);
    padding-block-start: var(--shelf-space-sm);
    border-block-start: var(--shelf-borderWidth-thin) solid var(--shelf-borderColor-subtle);
  }

  .card-footer-timestamp {
    color: var(--shelf-fgColor-muted);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-regular);
  }

  .card-footer-action {
    margin-inline-start: auto;
    color: var(--shelf-fgColor-accent);
    font-size: var(--shelf-font-size-xs);
    font-weight: var(--shelf-font-weight-medium);
    background: transparent;
    border: none;
    padding-block: var(--shelf-space-xs);
    padding-inline: var(--shelf-space-sm);
    border-radius: var(--shelf-radius-sm);
    cursor: pointer;
    transition: opacity var(--shelf-motion-duration-fast) var(--shelf-motion-easing-enter);
  }

  .card-footer-action:hover {
    opacity: var(--shelf-opacity-hover);
  }

  .card-footer-action:focus-visible {
    outline: var(--shelf-focusRing);
    outline-offset: var(--shelf-focusRing-offset);
  }
}
